mkdir -p <scratch>/scratchpad/analyze-tmp && cd $_ && cat > chk.py <<'EOF'
import re
from decimal import Decimal as D, ROUND_HALF_UP
R=lambda x: x.quantize(D('0.01'),rounding=ROUND_HALF_UP)
L=open('<home>/Projects/commission-calculator-sdlc/specs/001-commission-calculator/spec.md').read().split('\n')
def amt(s):
    s=s.strip().replace('$','').replace(',','')
    neg=s.startswith('−') or s.startswith('-')
    v=D(s.lstrip('−-')); return -v if neg else v
sec=None;rep=None;reps={}
for i,l in enumerate(L[595:],596):
    if l.startswith('### A.'): sec=l.split('`')[1]
    m=re.match(r'\*\*(\w+)\*\*$',l)
    if m: rep=(sec,m.group(1)); reps[rep]=[]
    elif rep and l.startswith('| ') and not l.startswith('| Item') and not l.startswith('|---'):
        c=[x.strip() for x in l.strip('|').split('|')]
        if len(c)==3 and c[2].startswith('FR-'): reps[rep].append((c[0],amt(c[1]),c[2],i))
    elif l.startswith('### '): rep=None
for k,ls in reps.items():
    g=lambda n:[a for d,a,f,i in ls if d==n]
    q=g('Quarterly quota')[0]; pq=(g('Prorated quota (' ) or [None])
    pqs=[a for d,a,f,i in ls if d.startswith('Prorated quota')]; pq=pqs[0] if pqs else q
    credit=sum([a for d,a,f,i in ls if f in('FR-008','FR-012') and d!='Credited bookings' and 'excluded' not in d],D(0))
    cb=g('Credited bookings')[0]
    if credit!=cb: print(k,'credit',credit,cb)
    tiers=[a for d,a,f,i in ls if f=='FR-006' and d!='Commission before refunds']
    cbr=g('Commission before refunds')[0]
    if sum(tiers,D(0))!=cbr: print(k,'cbr')
    e150=R(pq*D('1.5'))
    exp=[x for x in [R(D('0.05')*min(cb,pq)),R(D('0.08')*max(min(cb-pq,e150-pq),D(0))),R(D('0.12')*max(cb-e150,D(0)))] if x!=0]
    if exp!=tiers: print(k,'tiers',exp,tiers)
    cl=[a for d,a,f,i in ls if d.startswith('Clawback:')]; cls=g('Clawbacks')[0]
    if sum(cl,D(0))!=cls: print(k,'claw')
    earned=g('Earned commission')[0]
    if earned!=cbr-cls: print(k,'earned')
    dr=[a for d,a,f,i in ls if d.startswith('Draw,')]; dp=g('Draws paid')[0]
    if sum(dr,D(0))!=dp: print(k,'draws')
    op=g('Opening recoverable balance')[0]; tot=op+dp
    rec,pay,clo=g('Draw recovered')[0],g('Commission payable')[0],g('Closing recoverable balance')[0]
    if earned>=0: er,ep,ec=min(earned,tot),earned-min(earned,tot),tot-min(earned,tot)
    else: er,ep,ec=D(0),D(0),tot-earned
    if (er,ep,ec)!=(rec,pay,clo): print(k,'recovery',(er,ep,ec),(rec,pay,clo))
print(len(reps),'reps checked')
EOF
python3 chk.py

