input.command:
cd <scratch>/scratchpad/analyze-tmp && dotnet new webapp -o web --no-https >/dev/null 2>&1; dotnet new console -o tool >/dev/null 2>&1; cat >> web/Pages/Index.cshtml.cs <<'EOF'
[System.AttributeUsage(System.AttributeTargets.Class)] public sealed class ImplementsAttribute(string id) : System.Attribute { public string Id { get; } = id; }
EOF
sed -i '' 's/public class IndexModel/[Implements("FR-001")] public class IndexModel/' web/Pages/Index.cshtml.cs
cat > tool/Program.cs <<'EOF'
using System.Reflection;
var asm = Assembly.LoadFrom(args[0]);
try { foreach (var t in asm.GetTypes()) foreach (var a in t.GetCustomAttributesData()) if (a.AttributeType.Name=="ImplementsAttribute") Console.WriteLine($"{t.FullName} {a.ConstructorArguments[0].Value}"); Console.WriteLine("OK"); }
catch (Exception e) { Console.WriteLine("FAIL " + e.GetType().Name + ": " + e.Message.Split('\n')[0]); if (e is ReflectionTypeLoadException r) Console.WriteLine(r.LoaderExceptions[0]?.Message); }
EOF
(cd web && dotnet build -v q 2>&1 | tail -2); (cd tool && dotnet build -v q 2>&1 | tail -2); dotnet tool/bin/Debug/net10.0/tool.dll web/bin/Debug/net10.0/web.dll

